CREATE TABLE IF NOT EXISTS chapter_dependencies (project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, chapter_version_id VARCHAR(32) NOT NULL, canon_version BIGINT NOT NULL, dependency_kind VARCHAR(32) NOT NULL, dependency_id VARCHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(project_id,branch_id,chapter_version_id,dependency_kind,dependency_id), CONSTRAINT fk_chapter_dependency_version FOREIGN KEY(chapter_version_id) REFERENCES document_versions(id) ON DELETE CASCADE, INDEX idx_chapter_dependency_reverse(project_id,branch_id,dependency_kind,dependency_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS stale_chapters (project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, chapter_version_id VARCHAR(32) NOT NULL, trigger_canon_version BIGINT NOT NULL, reasons_json JSON NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(project_id,branch_id,chapter_version_id), CONSTRAINT fk_stale_chapter_version FOREIGN KEY(chapter_version_id) REFERENCES document_versions(id) ON DELETE CASCADE, INDEX idx_stale_chapters_project(project_id,branch_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
